//  - реджект 2 (Figma 868:12346): нет микрофона (getUserMedia → NotFoundError) → «הבדיקה לא הצליחה», подзаголовок
//    «לא נמצא מיקרופון…», под ним ОДИН блок «אפשר לבדוק שוב…» без значка ⓘ и без «…לא נפגע»; 390 и 1440 без прокрутки;
//  - реджект 1 (Figma 868:12307): сбой сохранения результата (candidate_tech_check оборван на «כן, שומעים טוב») →
//    «לא הצלחנו לשמור את תוצאת הבדיקה. נסו שוב.» по центру, цвет #E9967F; после восстановления — проверка проходит;
//  - AC4: доступ запрещён (NotAllowedError) в Chrome → «המיקרופון חסום» + инструкции для Chrome, дальше не пускает.
// Не автоматизировано: треб.5 — прохождение на настоящих телефонах (Pixel 6 Chrome / iPhone Safari, системное разрешение).
// НЕ prod-safe: каждый тест создаёт кандидата «QA-AUTO-e676bd-…» (business, link_only), не удаляется → @data.
// Официальная попытка и практика не начинаются (blockCallStarts); тех. проверка попытку не расходует (треб.3).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts, createCandidateLink, launchCandidate, tap } from './support';
import { newCandidateLink, tapBtn } from './a11y-support';
import { HELP, TECH, failGetUserMedia, noHorizontalScroll, toTechCheckIntro } from './help-1104-support';

const HASH = '#e676bd · #6a993d723354c77b66e676bd';

/** Экран «нет микрофона» по Figma 868:12346 (структура — как в подписанном тесте программиста M4-NOMIC-AC1). */
async function expectNoMicScreen(page: Page, label: string) {
  const heading = page.getByRole('heading', { name: TECH.failed });
  await expect(heading, label).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(TECH.noMic), `${label}: подзаголовок`).toBeVisible();
  await expect(page.getByText(TECH.noMicBox), `${label}: блок`).toHaveCount(1);
  await expect(page.getByText(/לא נפגע/), `${label}: лишняя заметка «…לא נפגע»`).toHaveCount(0);
  const s = await heading.evaluate((h, texts) => {
    const sub = h.nextElementSibling as HTMLElement | null;
    const content = h.parentElement?.parentElement as HTMLElement | null;
    const boxes = content ? Array.from(content.children).slice(1).filter((e) => (e as HTMLElement).innerText.trim()) : [];
    return {
      sub: (sub?.innerText || '').replace(/\s+/g, ' ').trim(),
      boxes: boxes.map((b) => (b as HTMLElement).innerText.replace(/\s+/g, ' ').trim()),
      icons: boxes.map((b) => b.querySelectorAll('svg, img').length),
      want: texts,
    };
  }, [TECH.noMic, TECH.noMicBox]);
  expect(s.sub, `${label}: подзаголовок сразу под «${TECH.failed}»`).toBe(TECH.noMic);
  expect(s.boxes, `${label}: под подзаголовком ровно один блок`).toEqual([TECH.noMicBox]);
  expect(s.icons, `${label}: значок ⓘ в блоке`).toEqual([0]);
  await expect(page.getByRole('button', { name: TECH.retry })).toBeVisible();
  await expect(page.getByRole('button', { name: HELP.techLink, exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: TECH.toPractice })).toHaveCount(0);
}

test.describe(`Кандидат — тех. проверка: нет микрофона, запрет доступа, сбой сохранения (${HASH})`, () => {
  test(`нет микрофона (NotFoundError) → «${TECH.failed}», «${TECH.noMic}», один блок «${TECH.noMicBox}» без ⓘ; «${TECH.retry}» и путь к человеку; без прокрутки @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-e676bd-M-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не пройдена), не удаляется` });
    await page.addInitScript(failGetUserMedia, 'NotFoundError');
    const blocked = await blockCallStarts(page);

    await toTechCheckIntro(page, link);
    await tapBtn(page, TECH.start);
    // Источник: реджект 2 (Figma 868:12346) + ответ программиста 02.11.
    await expectNoMicScreen(page, `своё окно ${page.viewportSize()!.width}`);
    await noHorizontalScroll(page, 'нет микрофона');

    // AC3 / треб.2: повтор без ограничений — «לבדוק שוב» снова ведёт на тот же экран, не блокирует.
    await tapBtn(page, TECH.retry);
    await expectNoMicScreen(page, 'после «לבדוק שוב»');
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`390 и 1440: экран «нет микрофона» как Figma 868:12346, без горизонтальной прокрутки @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-e676bd-D-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не пройдена), не удаляется` });
    await page.addInitScript(failGetUserMedia, 'NotFoundError');
    const blocked = await blockCallStarts(page);

    await toTechCheckIntro(page, link);
    await tapBtn(page, TECH.start);
    for (const w of [390, 1440]) {
      await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
      await expectNoMicScreen(page, `@${w}`);
      await noHorizontalScroll(page, `нет микрофона @${w}`);
    }
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`доступ запрещён (NotAllowedError) в Chrome → «${TECH.blocked}», «${TECH.blockedSub}», «${TECH.chromeHow}» и 3 шага; дальше не пускает @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-e676bd-B-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не пройдена), не удаляется` });
    await page.addInitScript(failGetUserMedia, 'NotAllowedError');
    const blocked = await blockCallStarts(page);

    await toTechCheckIntro(page, link);
    await tapBtn(page, TECH.start);
    // Источник: AC4 «ההמשך חסום ומוצגות הנחיות להסרת החסימה בדפדפן שבו אני נמצא» (скрин e676bd-denied-desktop.png).
    await expect(page.getByText(TECH.blocked, { exact: true }).first()).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(TECH.blockedSub).first()).toBeVisible();
    await expect(page.getByText(TECH.chromeHow)).toBeVisible();
    for (const step of TECH.chromeSteps) await expect(page.getByText(step).first(), `шаг «${step}»`).toBeVisible();
    await expect(page.getByText(/כך מאפשרים אותה ב-Safari/)).toHaveCount(0);
    await expect(page.getByRole('button', { name: TECH.toPractice })).toHaveCount(0);
    await expect(page.getByRole('button', { name: TECH.retry })).toBeVisible();
    await expect(page.getByRole('button', { name: HELP.techLink, exact: true })).toBeVisible();

    // «לבדוק שוב» без разрешения — снова блок, не пропускает.
    await tapBtn(page, TECH.retry);
    await expect(page.getByText(TECH.blocked, { exact: true }).first()).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('button', { name: TECH.toPractice })).toHaveCount(0);
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`сбой сохранения результата (candidate_tech_check оборван на «${TECH.heardOk}») → «${TECH.saveFail}» по центру, цвет #E9967F; сеть вернулась → «${TECH.toPractice}» @desktop @data ${HASH}`, async ({ asUser }, testInfo) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-e676bd-S-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (тех. проверка пройдена со второго раза), не удаляется` });

    // Chrome с фальшивым микрофоном (файл mic-check.wav), окно 390 — как в ручной проверке (скрин e676bd-saveerr-390.png).
    const cand = await launchCandidate({ width: 390, height: 844 });
    try {
      const { page, counts } = cand;
      await toTechCheckIntro(page, link);
      await tap(page, TECH.start);
      await expect(page.getByRole('button', { name: TECH.heardOk })).toBeVisible({ timeout: 60_000 });

      let aborted = 0;
      const TC = '**/rest/v1/rpc/candidate_tech_check';
      await page.route(TC, (r) => {
        aborted++;
        return r.abort('failed');
      });
      await tap(page, TECH.heardOk);

      // Источник: реджект 1 (Figma 868:12307): по центру, цвет #e9967f, под строкой «ודאו שהשמע של המכשיר פועל».
      const msg = page.getByText(TECH.saveFail);
      await expect(msg).toBeVisible({ timeout: 30_000 });
      expect(aborted, 'candidate_tech_check не вызывался').toBeGreaterThan(0);
      const st = await msg.evaluate((e) => {
        const cs = getComputedStyle(e);
        return { color: cs.color, align: cs.textAlign };
      });
      expect(st.color, 'цвет сообщения').toBe('rgb(233, 150, 127)');
      expect(st.align, 'выравнивание сообщения').toBe('center');
      const hint = await page.getByText('ודאו שהשמע של המכשיר פועל').boundingBox();
      const box = await msg.boundingBox();
      expect(hint && box && box.y >= hint.y + hint.height - 1, 'сообщение под строкой «ודאו שהשמע של המכשיר פועל»').toBeTruthy();
      await expect(page.getByRole('button', { name: TECH.toPractice })).toHaveCount(0);

      await page.unroute(TC);
      await tap(page, TECH.heardOk);
      await expect(page.getByRole('button', { name: TECH.toPractice })).toBeVisible({ timeout: 30_000 });
      await expect(msg).toHaveCount(0);
      expect(counts.start + counts.voice, 'старт попытки').toBe(0);
    } finally {
      await cand.browser.close();
    }
  });
});
